```javascript
const axios = require('axios'); // Make sure to install 'axios' package using npm or yarn before running the code

async function postMessageToSlack(text, channel) {
  try {
    const options = {
      method: 'post',
      url: `https://slack.com/api/chat.postMessage`,
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${process.env.SLACK_TOKEN}`,
      },
      data: {
        channel: channel,
        text: text,
      },
    };

    const response = await axios(options);

    if (response.status === 200) {
      console.log(`Message sent to #${channel}: ${text}`);
    } else {
      throw new Error(`Failed to send message to #${channel}. Status code: ${response.status}`);
    }
  } catch (error) {
    console.error(`Error sending message to #${channel}: ${error.message}`);
  }
}

// Replace 'your-slack-token' with your actual Slack token
postMessageToSlack('Hello, world!', '#general');
```

Replace `'your-slack-token'` with your actual Slack bot token. This function uses the `axios` library to make HTTP requests, so make sure you have it installed in your project. The function takes two arguments - the text message and the name of the Slack channel where the message should be posted. It then sends a POST request to the Slack API with the provided information. If the request is successful, it logs a confirmation message to the console. If there's an error, it logs the error message instead.

